#!/usr/bin/env python3
"""Air Jordan Sneaker Resale Market Analysis Report Generator.

All figures are derived directly from /app/benchmark/data.csv.
No numbers are fabricated.
"""

import csv
import json
from datetime import datetime
from collections import defaultdict
from pathlib import Path

import pandas as pd
import numpy as np


def load_data(csv_path: str) -> pd.DataFrame:
    df = pd.read_csv(csv_path)
    df["Sale_Date"] = pd.to_datetime(df["Sale_Date"])
    df["Year"] = df["Sale_Date"].dt.year
    df["Month"] = df["Sale_Date"].dt.month
    df["YearMonth"] = df["Sale_Date"].dt.to_period("M")
    df["Resale_to_Retail"] = df["Resale_Price_USD"] / df["Retail_Price_USD"]
    df["Above_Retail"] = df["Profit_Margin_USD"] > 0
    return df


def compute_kpis(df: pd.DataFrame) -> dict:
    avg_profit = df["Profit_Margin_USD"].mean()
    premium_rate = df["Above_Retail"].mean() * 100
    avg_days = df["Days_in_Inventory"].mean()
    avg_ratio = df["Resale_to_Retail"].mean()

    # Top-performing colorway by average profit margin
    colorway_margins = df.groupby("Colorway")["Profit_Margin_USD"].mean().sort_values(ascending=False)
    top_colorway = colorway_margins.index[0]
    top_colorway_margin = colorway_margins.iloc[0]

    return {
        "avg_profit_margin": round(avg_profit, 2),
        "premium_rate": round(premium_rate, 1),
        "avg_days_inventory": round(avg_days, 1),
        "avg_resale_to_retail": round(avg_ratio, 3),
        "top_colorway_name": top_colorway,
        "top_colorway_margin": round(top_colorway_margin, 2),
    }


def market_overview(df: pd.DataFrame) -> dict:
    total_tx = len(df)
    date_min = df["Sale_Date"].min().strftime("%Y-%m-%d")
    date_max = df["Sale_Date"].max().strftime("%Y-%m-%d")
    avg_retail = df["Retail_Price_USD"].mean()
    avg_resale = df["Resale_Price_USD"].mean()
    median_profit = df["Profit_Margin_USD"].median()

    # Profit margin distribution buckets
    bins = [-np.inf, -100, -50, -25, 0, 25, 50, 100, 200, 500, np.inf]
    labels = ["<-$100", "-$100 to -$50", "-$50 to -$25", "-$25 to $0",
              "$0 to $25", "$25 to $50", "$50 to $100", "$100 to $200",
              "$200 to $500", ">$500"]
    df["PM_Bucket"] = pd.cut(df["Profit_Margin_USD"], bins=bins, labels=labels, right=False)
    pm_dist = df["PM_Bucket"].value_counts().sort_index().to_dict()

    # Overall stats
    pct_above = df["Above_Retail"].mean() * 100
    pct_below = (df["Profit_Margin_USD"] < 0).mean() * 100
    max_profit = df["Profit_Margin_USD"].max()
    max_loss = df["Profit_Margin_USD"].min()

    return {
        "total_transactions": total_tx,
        "date_min": date_min,
        "date_max": date_max,
        "avg_retail": round(avg_retail, 2),
        "avg_resale": round(avg_resale, 2),
        "median_profit": round(median_profit, 2),
        "pm_distribution": {str(k): int(v) for k, v in pm_dist.items()},
        "pct_above_retail": round(pct_above, 1),
        "pct_below_retail": round(pct_below, 1),
        "max_profit": round(max_profit, 2),
        "max_loss": round(max_loss, 2),
    }


def model_analysis(df: pd.DataFrame) -> dict:
    models = df.groupby("Shoe_Model").agg(
        avg_resale=("Resale_Price_USD", "mean"),
        avg_profit=("Profit_Margin_USD", "mean"),
        avg_ratio=("Resale_to_Retail", "mean"),
        volume=("Transaction_ID", "count"),
        pct_above=("Above_Retail", "mean"),
    ).round(2)
    models["pct_above"] = (models["pct_above"] * 100).round(1)
    models = models.sort_values("avg_profit", ascending=False)

    colorways = df.groupby("Colorway").agg(
        avg_resale=("Resale_Price_USD", "mean"),
        avg_profit=("Profit_Margin_USD", "mean"),
        avg_ratio=("Resale_to_Retail", "mean"),
        volume=("Transaction_ID", "count"),
        pct_above=("Above_Retail", "mean"),
    ).round(2)
    colorways["pct_above"] = (colorways["pct_above"] * 100).round(1)
    colorways = colorways.sort_values("avg_profit", ascending=False)

    # Model x Colorway top combos
    model_color = df.groupby(["Shoe_Model", "Colorway"]).agg(
        avg_profit=("Profit_Margin_USD", "mean"),
        volume=("Transaction_ID", "count"),
    ).round(2).sort_values("avg_profit", ascending=False)

    return {
        "models": [
            {"name": idx, **{k: v for k, v in row.items()}}
            for idx, row in models.iterrows()
        ],
        "colorways": [
            {"name": idx, **{k: v for k, v in row.items()}}
            for idx, row in colorways.iterrows()
        ],
        "top_combos": [
            {"model": idx[0], "colorway": idx[1], "avg_profit": row["avg_profit"], "volume": int(row["volume"])}
            for idx, row in model_color.head(15).iterrows()
        ],
    }


def condition_analysis(df: pd.DataFrame) -> dict:
    cond = df.groupby("Condition").agg(
        avg_resale=("Resale_Price_USD", "mean"),
        avg_profit=("Profit_Margin_USD", "mean"),
        avg_ratio=("Resale_to_Retail", "mean"),
        volume=("Transaction_ID", "count"),
        pct_above=("Above_Retail", "mean"),
        avg_days=("Days_in_Inventory", "mean"),
        median_profit=("Profit_Margin_USD", "median"),
    ).round(2)
    cond["pct_above"] = (cond["pct_above"] * 100).round(1)

    # Condition profit ranges
    condition_order = ["Deadstock (Brand New)", "VNDS (Very Near Deadstock)", "Used"]
    cond_stats = []
    for c in condition_order:
        if c in cond.index:
            row = cond.loc[c]
            subset = df[df["Condition"] == c]
            cond_stats.append({
                "condition": c.replace(" (Brand New)", "").replace(" (Very Near Deadstock)", ""),
                "avg_resale": round(row["avg_resale"], 2),
                "avg_profit": round(row["avg_profit"], 2),
                "avg_ratio": round(row["avg_ratio"], 3),
                "volume": int(row["volume"]),
                "pct_above": round(row["pct_above"], 1),
                "avg_days": round(row["avg_days"], 1),
                "median_profit": round(row["median_profit"], 2),
                "p25_profit": round(subset["Profit_Margin_USD"].quantile(0.25), 2),
                "p75_profit": round(subset["Profit_Margin_USD"].quantile(0.75), 2),
            })

    return {"conditions": cond_stats}


def channel_analysis(df: pd.DataFrame) -> dict:
    ch = df.groupby("Sales_Channel").agg(
        avg_resale=("Resale_Price_USD", "mean"),
        avg_profit=("Profit_Margin_USD", "mean"),
        avg_ratio=("Resale_to_Retail", "mean"),
        volume=("Transaction_ID", "count"),
        pct_above=("Above_Retail", "mean"),
        avg_days=("Days_in_Inventory", "mean"),
        median_days=("Days_in_Inventory", "median"),
    ).round(2)
    ch["pct_above"] = (ch["pct_above"] * 100).round(1)
    ch = ch.sort_values("avg_profit", ascending=False)

    channels = []
    for idx, row in ch.iterrows():
        channels.append({
            "channel": idx,
            "avg_resale": round(row["avg_resale"], 2),
            "avg_profit": round(row["avg_profit"], 2),
            "avg_ratio": round(row["avg_ratio"], 3),
            "volume": int(row["volume"]),
            "pct_above": round(row["pct_above"], 1),
            "avg_days": round(row["avg_days"], 1),
            "median_days": round(row["median_days"], 1),
        })

    return {"channels": channels}


def temporal_analysis(df: pd.DataFrame) -> dict:
    # Yearly
    yearly = df.groupby("Year").agg(
        avg_resale=("Resale_Price_USD", "mean"),
        avg_profit=("Profit_Margin_USD", "mean"),
        avg_days=("Days_in_Inventory", "mean"),
        volume=("Transaction_ID", "count"),
        pct_above=("Above_Retail", "mean"),
    ).round(2)
    yearly["pct_above"] = (yearly["pct_above"] * 100).round(1)

    # Monthly
    monthly = df.groupby("YearMonth").agg(
        avg_resale=("Resale_Price_USD", "mean"),
        avg_profit=("Profit_Margin_USD", "mean"),
        avg_days=("Days_in_Inventory", "mean"),
        volume=("Transaction_ID", "count"),
        pct_above=("Above_Retail", "mean"),
    ).round(2)
    monthly["pct_above"] = (monthly["pct_above"] * 100).round(1)

    # Seasonality by calendar month (average across all years)
    seasonal = df.groupby("Month").agg(
        avg_profit=("Profit_Margin_USD", "mean"),
        avg_ratio=("Resale_to_Retail", "mean"),
        volume=("Transaction_ID", "mean"),
    ).round(2)

    return {
        "yearly": [
            {"year": int(idx), **{k: v for k, v in row.items()}}
            for idx, row in yearly.iterrows()
        ],
        "monthly": [
            {"period": str(idx), **{k: v for k, v in row.items()}}
            for idx, row in monthly.iterrows()
        ],
        "month_names": ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
                        "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
        "seasonal_profit": [round(seasonal.loc[m, "avg_profit"], 2) if m in seasonal.index else 0 for m in range(1, 13)],
        "seasonal_ratio": [round(seasonal.loc[m, "avg_ratio"], 3) if m in seasonal.index else 0 for m in range(1, 13)],
        "seasonal_volume": [round(seasonal.loc[m, "volume"], 1) if m in seasonal.index else 0 for m in range(1, 13)],
    }


