def main():
    csv_path = "/app/benchmark/data.csv"
    output_path = "/app/output/final_report.html"

    # Ensure output directory
    Path(output_path).parent.mkdir(parents=True, exist_ok=True)

    # Load
    df = load_data(csv_path)
    print(f"Loaded {len(df):,} transactions")

    # Compute
    kpis = compute_kpis(df)
    print(f"KPIs computed: avg_profit={kpis['avg_profit_margin']}, premium_rate={kpis['premium_rate']}%")

    overview = market_overview(df)
    models = model_analysis(df)
    conditions = condition_analysis(df)
    channels = channel_analysis(df)
    temporal = temporal_analysis(df)

    # Build HTML
    html = build_report_html(kpis, overview, models, conditions, channels, temporal)

    # Write
    Path(output_path).write_text(html)
    print(f"Report written to {output_path}")
    print(f"File size: {len(html):,} bytes")


if __name__ == "__main__":
    main()

