// ========== 2. RETAIL VS RESALE SCATTER ==========
(function() {{
  new Chart(document.getElementById('chartRetailVsResale'), {{
    type: 'scatter',
    data: {{
      datasets: [{{
        label: 'All Transactions',
        data: (function() {{
          // We compute average by condition for this chart from the conditions data
          return DATA.conditions.conditions.map(c => ({{
            x: c.avg_resale,
            y: c.avg_resale
          }}));
        }})(),
        backgroundColor: 'rgba(37,99,235,0.6)',
        pointRadius: 0,
      }}]
    }},
    options: {{
      responsive: true,
      plugins: {{
        title: {{ display: true, text: 'Average Price by Condition Tier', font: {{ size: 14 }} }}
      }},
      scales: {{
        x: {{ title: {{ display: true, text: 'Avg Resale Price (USD)' }} }}
      }}
    }}
  }});
}})();

tool_use_result.newString:
// ========== 2. RETAIL VS RESALE BY CONDITION ==========
(function() {{
  const conds = DATA.conditions.conditions;
  const labels = conds.map(c => c.condition);
  const retail = conds.map(c => {{
    // Average retail price from the conditions data; we need it from the overview
    // The retail prices vary, so we'll use avg_resale and avg_ratio to back-calculate
    return c.avg_ratio > 0 ? Math.round(c.avg_resale / c.avg_ratio) : 0;
  }});
  const resale = conds.map(c => c.avg_resale);

  // Instead, show condition price premiums
  new Chart(document.getElementById('chartRetailVsResale'), {{
    type: 'bar',
    data: {{
      labels: labels,
      datasets: [
        {{
          label: 'Avg Resale Price',
          data: resale,
          backgroundColor: 'rgba(37,99,235,0.7)',
          borderColor: '#2563eb',
          borderWidth: 1,
          borderRadius: 5,
        }},
        {{
          label: 'Market-wide Avg Resale',
          data: Array(labels.length).fill({overview['avg_resale']}),
          type: 'line',
          borderColor: '#d97706',
          backgroundColor: 'rgba(217,119,6,0.1)',
          borderWidth: 2,
          borderDash: [5,4],
          fill: false,
          pointRadius: 0,
        }}
      ]
    }},
    options: {{
      responsive: true,
      plugins: {{
        title: {{ display: true, text: 'Average Resale Price vs Market Average by Condition', font: {{ size: 14 }} }},
        legend: {{ display: true, position: 'bottom' }}
      }}
    }}
  }});
}})();

